const input=$json??{};
const dealId=input.deal_id??null; const leadId=input.lead_id??null; const propertyId=input.property_id??null;
const eventType=String(input.event_type??input.callback_type??input.receipt_type??'').toLowerCase();
const deliveryStatus=String(input.delivery_status??input.status??'').toLowerCase();
const providerMessageId=String(input.provider_message_id??input.message_id??input.external_message_id??'').trim();
const idempotencyKey=String(input.idempotency_key??'').trim();
const dnc=Boolean(input.dnc??input.do_not_contact??false); const blockers=Array.isArray(input.blockers)?input.blockers:[];
const sellerResponse=String(input.seller_response??input.inbound_message??'').trim();
let route='needs_review'; let nextWorkflow='WF-348'; let reason='Provider receipt requires review.';
if(dnc){route='blocked';nextWorkflow='WF-126';reason='DNC protection blocks further seller communication.';}
else if(blockers.length){route='blocked';nextWorkflow='WF-126';reason='Active blocker prevents response routing.';}
else if(!dealId||!leadId||!propertyId){route='incomplete';reason='Deal identity is incomplete.';}
else if(!idempotencyKey||!providerMessageId){route='invalid_receipt';reason='Provider receipt is missing idempotency or provider message identity.';}
else if(['delivered','delivery_success','sent','accepted'].includes(deliveryStatus)&&!sellerResponse){route='delivered_waiting_response';nextWorkflow='WF-350';reason='Outbound message was accepted/delivered; await seller response or timeout.';}
else if(['failed','undelivered','rejected','bounced'].includes(deliveryStatus)){route='delivery_failed';nextWorkflow='WF-350';reason='Provider reports delivery failure; controlled retry/fallback review required.';}
else if(sellerResponse){route='seller_response_received';nextWorkflow='WF-342';reason='Seller response detected; route to AI classification and negotiation routing.';}
else if(eventType==='inbound_message'||eventType==='seller_response'){route='seller_response_received';nextWorkflow='WF-342';reason='Inbound seller response event detected.';}
else{route='needs_review';nextWorkflow='WF-348';reason='Receipt/callback event is not recognized.';}
const receipt={provider_message_id:providerMessageId,idempotency_key:idempotencyKey,event_type:eventType,delivery_status:deliveryStatus,seller_response:sellerResponse,deal_id:dealId,lead_id:leadId,property_id:propertyId};
const activity={activity_type:'provider_delivery_receipt_callback',subject:'WF-349 '+(dealId??'unknown-deal'),deal_id:dealId,lead_id:leadId,property_id:propertyId,route,next_workflow:nextWorkflow,provider_message_id:providerMessageId,idempotency_key:idempotencyKey,event_type:eventType,delivery_status:deliveryStatus,seller_response_received:Boolean(sellerResponse),dnc,blockers,receipt,reason};
return [{json:{...input,wf_id:'WF-349',route,next_workflow:nextWorkflow,receipt,reason,crm_activity:activity,evaluated_at:new Date().toISOString()}}];
